class Solution {
    public long gridGame(int[][] grid) {
        int n = grid[0].length;
        long topSum = 0;
        for (int x : grid[0]) topSum += x;
        long bottomSum = 0;
        long ans = Long.MAX_VALUE;
        for (int c = 0; c < n; c++) {
            topSum -= grid[0][c];
            ans = Math.min(ans, Math.max(topSum, bottomSum));
            bottomSum += grid[1][c];
        }
        return ans;
    }
}

